n  /// Razão social fiscal. `name` é o display comercial (pode divergir);\n  /// aqui fica o rótulo exato usado em documentos legais (Portaria 671).\n  razaoSocial String? @map(\"razao_social\")\n\n  /// Preferências de login do portal do cliente (cpfSenha, chassi).\n  checklistLogin Json? @map(\"checklist_login\")\n\n  /// Snapshot do contrato — preservamos o shape completo do legacy pra\n  /// não perder informação enquanto o domínio de contratos não é modelado.\n  contract Json?\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  users                   CompanyUser[]\n  roles                   CompanyRole[]\n  pontoRegistros          PontoRegistro[]\n  pontoSolicitacoes       PontoSolicitacao[]\n  pontoAbonos             PontoAbono[]\n  pontoNsrCounter         PontoNsrCounter?\n  checklistsDevolucao     ChecklistDevolucao[]\n  checklistsChegada       ChecklistChegada[]\n  garantias               Garantia[]\n  orcamentos              Orcamento[]\n  features                CompanyFeature[]\n  featureChanges          CompanyFeatureChange[]\n  partners                Partner[]\n  partnerPortalUsers      PartnerPortalUser[]\n  equipments              Equipment[]\n  checklistRuns           ChecklistRun[]\n  serviceOrders           ServiceOrder[]\n  operators               Operator[]\n  abastecimentos          Abastecimento[]\n  workFronts              WorkFront[]\n  settings                CompanySettings?\n  emergencies             Emergency[]\n  creditos                Credito[]\n  lubrificacoes           Lubrificacao[]\n  reabastecimentosComboio ComboioReabastecimento[]\n  notasFiscais            NotaFiscal[]\n  planoPreventivo         PlanoPreventivo?\n  fleetfuelIntencoes      FleetfuelIntencao[]\n  notificacoes            Notificacao[]\n  whatsappRecipients      CompanyWhatsappRecipient[]\n\n  @@map(\"clients\")\n}\n\n/// Destinatários de WhatsApp para alertas de emergência (lista por empresa).\nmodel CompanyWhatsappRecipient {\n  id        String  @id @default(uuid()) @db.Uuid\n  companyId String  @map(\"company_id\") @db.Uuid\n  /// Rótulo opcional — ex: \"Plantão\", \"Gestor de frota\".\n  label     String?\n  telefone  String\n  ativo     Boolean @default(true)\n  sortOrder Int     @default(0) @map(\"sort_order\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  company Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  @@index([companyId, sortOrder])\n  @@map(\"company_whatsapp_recipients\")\n}\n\n/// Sessão mestre Baileys da plataforma (remetente único de emergências).\n/// Singleton — `id` fixo em `default`. Credenciais serializadas via BufferJSON.\nmodel WhatsappPlatformSession {\n  id String @id @default(\"default\")\n\n  creds String? @db.Text\n  keys  String? @db.Text\n\n  conectadoDesde DateTime? @map(\"conectado_desde\")\n  versaoSessao   String?   @map(\"versao_sessao\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@map(\"whatsapp_platform_sessions\")\n}\n\n/// Parâmetros operacionais da empresa (1:1 com Company). Consolida as três\n/// seções da tela /empresa/[slug]/configuracoes: alertas, comportamento do\n/// bloqueio de revisão e escala da jornada. Espelhado em Firestore nas\n/// collections `configuracoes/{legacyId}` e `escala/{legacyId}` pra manter\n/// compat com o portal 360 legacy.\nmodel CompanySettings {\n  companyId String @id @map(\"company_id\") @db.Uuid\n\n  /// Alertas e notificações — 6 toggles independentes.\n  alertBloqueioRevisaoVencida Boolean @default(true) @map(\"alert_bloqueio_revisao_vencida\")\n  alertNivelCriticoTanque     Boolean @default(true) @map(\"alert_nivel_critico_tanque\")\n  alertAbastecimentoIrregular Boolean @default(true) @map(\"alert_abastecimento_irregular\")\n  alertCnhProximaVencimento   Boolean @default(true) @map(\"alert_cnh_proxima_vencimento\")\n  alertRelatorioSemanal       Boolean @default(false) @map(\"alert_relatorio_semanal\")\n  alertWhatsappEmergencia     Boolean @default(false) @map(\"alert_whatsapp_emergencia\")\n\n  /// Comportamento do bloqueio de revisão.\n  bloquearAoVencer Boolean @default(true) @map(\"bloquear_ao_vencer\")\n  alertar80        Boolean @default(true) @map(\"alertar_80\")\n  alertar90        Boolean @default(true) @map(\"alertar_90\")\n\n  /// Escala da jornada — HH:MM 24h, almoço em minutos, dias 0=Dom..6=Sab.\n  escalaInicio    String @default(\"08:00\") @map(\"escala_inicio\")\n  escalaFim       String @default(\"18:00\") @map(\"escala_fim\")\n  escalaAlmocoMin Int    @default(60) @map(\"escala_almoco_min\")\n  escalaDias      Json   @default(\"[1,2,3,4,5]\") @map(\"escala_dias\")\n\n  /// Intervalos de revisão padrão por categoria de equipamento — usados pra\n  /// pré-preencher `Equipment.intervaloRevisao` no formulário de novo\n  /// equipamento (mesmo papel do `configPadrao.intervalos` do 360 legacy).\n  /// Shape: { carro, caminhao, maquina, ambulancia, van } com { valor, unidade }.\n  /// Não editável na tela de Configurações (paridade com o legado).\n  intervalos Json @default(\"{\\\"carro\\\":{\\\"valor\\\":1000,\\\"unidade\\\":\\\"km\\\"},\\\"caminhao\\\":{\\\"valor\\\":500,\\\"unidade\\\":\\\"horas\\\"},\\\"maquina\\\":{\\\"valor\\\":500,\\\"unidade\\\":\\\"horas\\\"},\\\"ambulancia\\\":{\\\"valor\\\":1000,\\\"unidade\\\":\\\"km\\\"},\\\"van\\\":{\\\"valor\\\":1000,\\\"unidade\\\":\\\"km\\\"}}\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  company Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  @@map(\"company_settings\")\n}\n\n/// Equipamento (frota). Campos ricos migrados do Firestore `equipamentos/{id}`\n/// pra suportar o painel da empresa (marca/modelo, medição, revisão, frente).\nmodel Equipment {\n  id        String  @id @default(uuid()) @db.Uuid\n  legacyId  String? @unique @map(\"legacy_id\")\n  companyId String  @map(\"company_id\") @db.Uuid\n\n  /// Bruto do legado: \"ativo\" | \"bloqueado\" | \"inativo\" | \"manutencao\" | ...\n  status String\n\n  /// Identificação e descrição\n  descricao String?\n  tipo      String?\n  linha     String?\n  placa     String?\n  chassi    String?\n  marca     String?\n  modelo    String?\n  ano       String?\n\n  /// Medição e revisão — usado por \"Próximas manutenções\" e \"Bloqueados\".\n  medicaoAtual     Float?  @map(\"medicao_atual\")\n  intervaloRevisao Float?  @map(\"intervalo_revisao\")\n  ultimaRevisao    Float?  @map(\"ultima_revisao\")\n  /// \"km\" | \"h\" (horímetro)\n  unidadeRevisao   String? @map(\"unidade_revisao\")\n\n  /// Frente de trabalho atual (string livre igual legado); vazio = \"Disponível\".\n  obra String?\n\n  /// Identificação estendida (formulário completo).\n  renavam        String?\n  numeroSerie    String? @map(\"numero_serie\")\n  patrimonioBase String? @map(\"patrimonio_base\")\n\n  /// Veículo estendido.\n  cor                      String?\n  combustivel              String?\n  /// \"Própria\" | \"Locada\" (rótulo do legado).\n  tipoFrota                String?  @map(\"tipo_frota\")\n  motorizacao              String?\n  anoModelo                String?  @map(\"ano_modelo\")\n  capacidadeTanque         Float?   @map(\"capacidade_tanque\")\n  /// Só faz sentido pra comboio (tanque acoplado ao caminhão em si).\n  capacidadeTanqueCaminhao Float?   @map(\"capacidade_tanque_caminhao\")\n  /// Volume atual do tanque do comboio (L). Substitui `tanks/{comboioId}`.\n  volumeTanqueAtual        Float?   @default(0) @map(\"volume_tanque_atual\")\n  valorVeiculo             Decimal? @map(\"valor_veiculo\") @db.Decimal(12, 2)\n\n  /// Operação — responsáveis. `condutoresIds` é `string[]` de `legacyId`\n  /// de Operator (soft-ref pra tolerar operador removido).\n  condutoresIds     Json    @default(\"[]\") @map(\"condutores_ids